		'no_meta'        => [ 'label' => 'بدون توضیح متا', 'level' => 'warn', 'effort' => 1, 'fix' => 'گوگل خلاصه نتیجه را بیشتر از خود متن صفحه می‌سازد و نبود توضیح متا را مشکل نمی‌داند؛ ولی توصیه می‌کند دست‌کم برای صفحه‌های مهم (صفحه اصلی و پربازدیدها) بنویسید. در «{where}» کادر «سئو (SeoBox)» را باز کنید و در «توضیحات متا» توضیحی بنویسید که نوار شمارنده سبز شود (' . $n( $m['min'] ) . ' تا ' . $n( $m['max'] ) . ' پیکسل)؛ کلمه اصلی صفحه در جمله اول بیاید.' ],
		'no_snippet'     => [ 'label' => 'متن زیر عنوان ممنوع', 'level' => 'bad', 'effort' => 1, 'fix' => 'در «{where}» کادر «سئو (SeoBox)»، بخش «پیشرفته»، حداکثر طول متن (max-snippet) را روی پیش‌فرض بگذارید؛ مقدار ۰ به گوگل می‌گوید زیر عنوان متنی نشان ندهد و نرخ کلیک را کم می‌کند.' ],
		'no_h1'          => [ 'label' => 'بدون H1', 'level' => 'warn', 'effort' => 1, 'fix' => 'هر صفحه یک تیتر اصلی (H1) لازم دارد.' ],
		'no_title'       => [ 'label' => 'بدون عنوان', 'level' => 'bad', 'effort' => 1, 'fix' => 'در «{where}» کادر «سئو (SeoBox)» را باز کنید و «عنوان سئو» بنویسید.' ],
		'title_short'    => [ 'label' => 'عنوان کوتاه', 'level' => 'info', 'effort' => 1, 'fix' => 'گوگل برای طول عنوان حداقلی ندارد؛ اگر عنوان توصیفی و کامل است (مثل «تماس با ما | نام سایت») نیازی به تغییر نیست. فقط اگر عنوان مبهم یا نیمه‌خالی است (مثل «خانه») در «{where}» کادر «سئو (SeoBox)» ← «عنوان سئو» آن را توصیفی‌تر کنید.' ],
